# app/crud/document_generator.py
# Turns AI-generated text into a professional .docx file
# pip install python-docx

import os
from datetime import datetime
from docx import Document
from docx.shared import Pt, Inches, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH


# ── Folder where generated files are saved ──────────────────────────────────
# Goes to:  <project_root>/generated_documents/
# Two dirname() calls: one for crud/, one for app/
_PROJECT_ROOT  = os.path.dirname(os.path.dirname(os.path.dirname(__file__)))
DOCUMENTS_DIR  = os.path.join(_PROJECT_ROOT, "generated_documents")

# Cognify brand blue  (#1360E2)
BRAND_BLUE = RGBColor(0x13, 0x60, 0xE2)
GRAY       = RGBColor(0x88, 0x88, 0x88)


def _ensure_dir():
    """Creates the output folder if it doesn't exist yet."""
    os.makedirs(DOCUMENTS_DIR, exist_ok=True)


def _safe_filename(title: str) -> str:
    """
    Converts a title like 'Integration by Parts!'
    into a safe filename like 'Integration_by_Parts'.
    """
    safe = "".join(c if (c.isalnum() or c in " _-") else "" for c in title)
    safe = safe.strip().replace(" ", "_")[:40]   # max 40 chars
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    return f"{safe}_{timestamp}.docx"


def _set_page_margins(doc: Document):
    for section in doc.sections:
        section.top_margin    = Inches(1.0)
        section.bottom_margin = Inches(1.0)
        section.left_margin   = Inches(1.25)
        section.right_margin  = Inches(1.25)


def _add_title_block(doc: Document, title: str, subject: str):
    """Centered title + subtitle metadata line."""
    # Main title
    tp = doc.add_paragraph()
    tp.alignment = WD_ALIGN_PARAGRAPH.CENTER
    tr = tp.add_run(title)
    tr.bold = True
    tr.font.size = Pt(20)
    tr.font.name = "Calibri"
    tr.font.color.rgb = BRAND_BLUE

    # Metadata: subject · date · "Generated by Cognify AI"
    mp = doc.add_paragraph()
    mp.alignment = WD_ALIGN_PARAGRAPH.CENTER
    date_str = datetime.now().strftime("%B %d, %Y")
    mr = mp.add_run(f"{subject}  •  {date_str}  •  Generated by Cognify AI")
    mr.font.size = Pt(10)
    mr.font.name = "Calibri"
    mr.font.color.rgb = GRAY

    # Horizontal rule (hairline paragraph border — simplest approach)
    doc.add_paragraph()


def _parse_and_write_content(doc: Document, content: str):
    """
    Parses the AI-generated text line by line and maps it to
    Word styles so the output looks structured, not like a wall of text.

    Supported markers (AI is prompted to use these):
      # Heading 1
      ## Heading 2
      - bullet item
      1. numbered item
      **bold line**
      (everything else = normal paragraph)
    """
    for line in content.split("\n"):
        stripped = line.strip()

        if not stripped:
            doc.add_paragraph()   # blank spacer
            continue

        if stripped.startswith("## "):
            h = doc.add_heading(stripped[3:], level=2)
            if h.runs:
                h.runs[0].font.color.rgb = BRAND_BLUE

        elif stripped.startswith("# "):
            h = doc.add_heading(stripped[2:], level=1)
            if h.runs:
                h.runs[0].font.color.rgb = BRAND_BLUE

        elif stripped.startswith(("- ", "• ")):
            p = doc.add_paragraph(style="List Bullet")
            r = p.add_run(stripped[2:])
            r.font.name = "Calibri"
            r.font.size = Pt(11)

        elif len(stripped) > 2 and stripped[0].isdigit() and stripped[1] in ".)" :
            # "1. item"  or  "1) item"
            text = stripped[2:].strip()
            p = doc.add_paragraph(style="List Number")
            r = p.add_run(text)
            r.font.name = "Calibri"
            r.font.size = Pt(11)

        elif stripped.startswith("**") and stripped.endswith("**"):
            p = doc.add_paragraph()
            r = p.add_run(stripped[2:-2])
            r.bold = True
            r.font.name = "Calibri"
            r.font.size = Pt(11)

        else:
            p = doc.add_paragraph()
            r = p.add_run(stripped)
            r.font.name = "Calibri"
            r.font.size = Pt(11)


def _add_footer(doc: Document):
    doc.add_paragraph()
    fp = doc.add_paragraph()
    fp.alignment = WD_ALIGN_PARAGRAPH.CENTER
    fr = fp.add_run("— Prepared with Cognify AI Assistant (CoCo) —")
    fr.font.size  = Pt(9)
    fr.italic     = True
    fr.font.color.rgb = GRAY


async def create_assignment_docx(
    title: str,
    content: str,
    subject: str = "General",
) -> str:
    """
    Assembles the full DOCX document and saves it to disk.

    Returns:
        filename (str) — e.g. 'Integration_by_Parts_20250619_143022.docx'
        The download route uses this filename to serve the file.
    """
    _ensure_dir()

    doc = Document()
    _set_page_margins(doc)
    _add_title_block(doc, title, subject)
    _parse_and_write_content(doc, content)
    _add_footer(doc)

    filename = _safe_filename(title)
    filepath  = os.path.join(DOCUMENTS_DIR, filename)
    doc.save(filepath)

    return filename